using System.Collections.Concurrent;using AfriWallet.Merchants.Intelligence.Application.Abstractions;using AfriWallet.Merchants.Intelligence.Domain.Findings;namespace AfriWallet.Merchants.Intelligence.Infrastructure;public sealed class InMemoryMerchantIntelligenceRepository:IMerchantIntelligenceRepository{private readonly ConcurrentDictionary<string,MerchantRiskFinding> _items=new(StringComparer.OrdinalIgnoreCase);public Task SaveAsync(MerchantRiskFinding finding,CancellationToken cancellationToken=default){cancellationToken.ThrowIfCancellationRequested();_items[finding.MerchantId]=finding;return Task.CompletedTask;}public Task<MerchantRiskFinding?> GetLatestAsync(string merchantId,CancellationToken cancellationToken=default){cancellationToken.ThrowIfCancellationRequested();_items.TryGetValue(merchantId,out var result);return Task.FromResult(result);}}public sealed class InMemoryMerchantIntelligenceAuditStore:IMerchantIntelligenceAuditStore{private readonly ConcurrentQueue<MerchantIntelligenceAuditEvent> _events=new();public Task AppendAsync(MerchantIntelligenceAuditEvent auditEvent,CancellationToken cancellationToken=default){cancellationToken.ThrowIfCancellationRequested();_events.Enqueue(auditEvent);return Task.CompletedTask;}public Task<IReadOnlyCollection<MerchantIntelligenceAuditEvent>> GetAsync(Guid findingId,CancellationToken cancellationToken=default){cancellationToken.ThrowIfCancellationRequested();IReadOnlyCollection<MerchantIntelligenceAuditEvent> result=_events.Where(x=>x.FindingId==findingId).ToArray();return Task.FromResult(result);}}public sealed class SystemMerchantIntelligenceClock:IMerchantIntelligenceClock{public DateTimeOffset UtcNow=>DateTimeOffset.UtcNow;}
